add('GBIF original butterfly download','2001–2024; predictors use pre-origin records','Original coordinates/date; model equal-area 10km cells',f"{occ['total_records']} records / {occ['species']} species from 225 candidates",'Official download metadata checked2026-11-05: CC BY-NC4.0; DOI10.15468/dl.umqmsf','Occurrence dates precede each predictor origin; archive retrieved retrospectively','Provider-day records are not visits or true occupancy; full future record pool must not define history','outputs/temporal_source_audit.json; outputs/forecast_model_lock.json; outputs/gbif_original_download_terms_audit.json')
